  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});
```

**Accounts** (`routes/accounts.js`): the account's own id is the scope. Bind the query to `req.user.accountId` instead of the URL value. Reject any URL id that isn't the caller's own, so `/accounts/<someone else>` can't silently act on the caller's account.

```js
function ownAccount(req, res, next) {
  if (req.params.id !== String(req.user.accountId)) return res.status(404).end();
  next();
}

router.patch("/:id", ownAccount, async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 RETURNING *",
    [req.body.display_name, req.body.billing_email, req.user.accountId]
  );
  res.json(row);
});

router.delete("/:id", ownAccount, async (req, res) => {
  await db.write("UPDATE accounts SET deleted_at = now() WHERE id = $1 RETURNING id",
    [req.user.accountId]);
  res.status(204).end();
});
```

